questionvariables.text:
num1:rand([1,1,-1])*(10*(rand(90)+10)+rand(9)+1)/rand([10,100,1000]);
num2:rand([1,1,-1])*(10*(rand(90)+10)+rand(9)+1)/rand([10,100,1000]);

num3:rand([1,1,-1])*(10*(rand(900)+100)+rand(9)+1)/rand([100,1000,10000]);
num4:rand([1,1,-1])*(10*(rand(900)+100)+rand(9)+1)/rand([100,1000,10000]);

num5:rand([1,1,-1])*(10*(rand(9000)+1000)+rand(9)+1)/rand([100,1000,10000]);

chooseNums:rand_selection([num1,num2,num3,num4,num5], 2);

num6: if abs(first(chooseNums))>100 then rand([1,-1])*first(chooseNums)/rand([10,100,1000]) else if abs(first(chooseNums))>10 then rand([1,-1])*first(chooseNums)/rand([10,100]) else if abs(first(chooseNums))>1 then rand([1,-1])*first(chooseNums)*rand([10,1/10]) else rand([1,-1])*first(chooseNums)*rand([10,100]);

num7: if second(chooseNums)>0 then rand(20)+ceiling(second(chooseNums))-second(chooseNums) else -(rand(20)+ceiling(second(chooseNums)))-second(chooseNums);

fracList:sort([num1,num2,num3,num4,num5,num6,num7]);
floatList:random_permutation([float(num1),float(num2),float(num3),float(num4),float(num5),float(num6),float(num7)]);

tans1:[decimalplaces(num1,1),decimalplaces(num2,1),decimalplaces(num3,1),decimalplaces(num4,1),decimalplaces(num5,1),decimalplaces(num6,1),decimalplaces(num7,1)];

tans2:float(lmax(fracList)+lmin(fracList));

tans3:float(fifth(fracList)-fourth(fracList));

tans4: if integerp(num6/first(chooseNums)) then float(num6) else float(first(chooseNums));
tans5: if integerp(num6/first(chooseNums)) then float(first(chooseNums)) else float(num6);
tans6: if integerp(num6/first(chooseNums)) then num6/first(chooseNums) else first(chooseNums)/num6;

tans7:float(num7);
tans8:float(second(chooseNums));
tans9:num7+second(chooseNums);

absSort(a,b) := abs(a)<abs(b);
tans10:first(sort(floatList, absSort));
tans11:second(sort(floatList, absSort));

